with subscriptions_by_customer as (select customer_id, count(monthly_fee) as monthly_fee_count from subscriptions group by customer_id) select customers.id, customers.city, subscriptions_by_customer.monthly_fee_count from customers join subscriptions_by_customer on customers.id = subscriptions_by_customer.customer_id where subscriptions_by_customer.monthly_fee_count > 7 order by id desc limit 1
